WITH with_windows AS (SELECT *, SUM(cost) OVER (PARTITION BY carrier, order_id) carrier_sum_cost, SUM(cost) OVER w_part cumulative_cost, ROUND(cost / SUM(cost) OVER (PARTITION BY status, carrier), 4) cost_share, FIRST_VALUE(cost, TRUE) OVER w_part first_known_cost, ROW_NUMBER() OVER w_recent event_seq FROM shipments WINDOW w_part AS (PARTITION BY status ORDER BY shipped_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW), w_recent AS (PARTITION BY MONTH(delivered_date) ORDER BY delivered_date DESC, id)) SELECT status, MIN(cumulative_cost) AS min_cumulative_cost, SIZE(COLLECT_SET(carrier)) AS num_carriers, APPROX_PERCENTILE(event_seq, ARRAY(0.25, 0.5, 0.75)) AS event_seq_quartiles, SORT_ARRAY(COLLECT_SET(carrier)) AS carrier_list, ROUND(SUM(carrier_sum_cost) / NULLIF(COUNT(CASE WHEN status = 'RETURNED' THEN 1 END), 0), 2) AS carrier_sum_cost_per_returned, SUM(cost_share) AS total_cost_share FROM with_windows GROUP BY status HAVING SUM(cost_share) >= 0
